import test from "node:test";import assert from "node:assert/strict";import {listOrders} from "./api.mjs";import {readOrders} from "./client.mjs";
test("API and client agree on pagination contract",async()=>{const input=[{id:3},{id:1},{id:2}];const first=listOrders(input,0,2);assert.deepEqual(first,{items:[{id:1},{id:2}],nextCursor:2});const all=await readOrders(async cursor=>listOrders(input,cursor,2));assert.deepEqual(all,[{id:1},{id:2},{id:3}]);assert.deepEqual(input,[{id:3},{id:1},{id:2}]);});
test("empty pages terminate and errors propagate",async()=>{assert.deepEqual(await readOrders(async()=>({items:[],nextCursor:null})),[]);await assert.rejects(readOrders(async()=>{throw new Error("network")}),/network/);assert.throws(()=>listOrders([],0,0));});
